import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

const INIT = [{ id: "1", name: "Чихэвч" }, { id: "2", name: "Цүнх" }, { id: "3", name: "Ном" }];

function reducer(state, action) {
  // энд бичнэ үү: "remove" action — action.id-тай барааг хас
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, INIT);
  return (
    <FlatList
      style={styles.s}
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => (
        <View testID="row" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Pressable nativeID={"del-" + item.id} style={styles.b} onPress={() => dispatch({ type: "remove", id: item.id })}><Text style={styles.t}>Устгах</Text></Pressable>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16 },
  row: { flexDirection: "row", alignItems: "center", padding: 14, backgroundColor: "#f8fafc", borderRadius: 12, marginBottom: 10 },
  name: { flexGrow: 1, fontSize: 16 }, b: { backgroundColor: "#dc2626", paddingHorizontal: 14, paddingVertical: 8, borderRadius: 8 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

const INIT = [{ id: "1", name: "Чихэвч" }, { id: "2", name: "Цүнх" }, { id: "3", name: "Ном" }];

function reducer(state, action) {
  if (action.type === "remove") return state.filter((item) => item.id !== action.id);
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, INIT);
  return (
    <FlatList
      style={styles.s}
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => (
        <View testID="row" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Pressable nativeID={"del-" + item.id} style={styles.b} onPress={() => dispatch({ type: "remove", id: item.id })}><Text style={styles.t}>Устгах</Text></Pressable>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16 },
  row: { flexDirection: "row", alignItems: "center", padding: 14, backgroundColor: "#f8fafc", borderRadius: 12, marginBottom: 10 },
  name: { flexGrow: 1, fontSize: 16 }, b: { backgroundColor: "#dc2626", paddingHorizontal: 14, paddingVertical: 8, borderRadius: 8 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
